<?php require 'config/config.php';if(user())go(BASE_URL.'/dashboard.php');$err='';if($_POST){check();$n=trim($_POST['name']);$em=trim($_POST['email']);$ph=trim($_POST['phone']);$pw=$_POST['password'];$role=in_array($_POST['role'],['tenant','owner'])?$_POST['role']:'tenant';if(!$n||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<6)$err='Enter valid details and a password of at least 6 characters.';else try{db()->prepare('INSERT INTO users(name,email,phone,password,role) VALUES(?,?,?,?,?)')->execute([$n,$em,$ph,password_hash($pw,PASSWORD_DEFAULT),$role]);go(BASE_URL.'/login.php');}catch(Exception $x){$err='Email already exists.';}}$title='Register';require 'config/header.php';?><div class="auth"><div class="panel"><h1>Create account</h1><?php if($err):?><div class="err"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Phone<input name="phone"></label><label>Password<input name="password" type="password" required></label><label>Role<select name="role"><option value="tenant">Tenant</option><option value="owner">Owner</option></select></label><button class="btn">Create Account</button></form></div></div><?php require 'config/footer.php';?>
